// Patrón callback con Action: notificar cuando termina algo
public class AnimacionManager : MonoBehaviour
{
    // Recibe un callback que se llama al terminar
    public void ReproducirAnimacion(string nombre, Action onComplete)
    {
        StartCoroutine(AnimarYNotificar(nombre, onComplete));
    }

    IEnumerator AnimarYNotificar(string nombre, Action onComplete)
    {
        Debug.Log("Animando: " + nombre);
        yield return new WaitForSeconds(1f);
        onComplete?.Invoke(); // llama al callback al terminar
    }
}

// Uso: pasar lambda como callback
public class EnemyController : MonoBehaviour
{
    [SerializeField] AnimacionManager anim;

    void Die()
    {
        anim.ReproducirAnimacion("Muerte", () =>
        {
            Debug.Log("Animación terminada, destruyendo objeto");
            Destroy(gameObject);
        });
    }
}

using System.Linq;

List<int> scores = new List<int> { 15, 42, 8, 97, 23, 55 };

// Where: filtrar (usa Predicate/Func<T, bool>)
var altos = scores.Where(s => s > 30);
// altos: { 42, 97, 55 }

// Select: transformar (proyectar)
var dobles = scores.Select(s => s * 2);
// dobles: { 30, 84, 16, 194, 46, 110 }

// FirstOrDefault: primer elemento que cumple condición
int primeroAlto = scores.FirstOrDefault(s => s > 50); // 97

// OrderBy: ordenar
var ordenados = scores.OrderBy(s => s);
// ordenados: { 8, 15, 23, 42, 55, 97 }

// Any / All
bool hayMayorA90 = scores.Any(s => s > 90);  // true
bool todosPositivos = scores.All(s => s > 0); // true

// Uso típico en Unity: filtrar enemigos activos
var vivos = FindObjectsOfType<Enemy>().Where(e => e.HP > 0).ToList();

